"use client";

/**
 * Search bar: a wide field types its query, rises, and a results list drops
 * in under it with the matching words marked and the first result focused.
 *
 * Written by Better Design. Painted from the theme prop, so the marks and the
 * focus take the product's primary colour.
 */
import { loadFont } from "@remotion/google-fonts/Inter";
import { AbsoluteFill, useCurrentFrame, useVideoConfig } from "remotion";
import { easings, pickFont, progress, TextField, typed, type VideoTheme, useVideoTheme, withAlpha } from "@/lib/bd-video";

const { fontFamily: INTER } = loadFont("normal", { weights: ["400", "500", "600"], subsets: ["latin"] });

const FIELD_FRAMES = 14;
const TYPE_AT = 16;
const RISE_AT = 48;
const RISE_FRAMES = 20;
const ROWS_AT = 56;
const ROW_GAP = 5;
const FOCUS_AT = 84;
const WIDTH = 1300;
const LEFT = (1920 - WIDTH) / 2;
const START_TOP = 496;
const END_TOP = 200;

export interface SearchBarProps {
  /** The query that types itself into the field. */
  query?: string;
  /** The results that drop in. Words that match the query are marked. */
  results?: string[];
  /** Grey text in the empty field. */
  placeholder?: string;
  theme?: Partial<VideoTheme>;
  /** A CSS font family the project has loaded. Defaults to the theme's face, then Inter. */
  font?: string;
}

const clean = (word: string): string => word.toLowerCase().replace(/[^\p{L}\p{N}]/gu, "");

/** Split a result into runs, joining matched words and the spaces between them into one mark. */
function segments(text: string, terms: Set<string>): { text: string; mark: boolean }[] {
  const parts = text.split(/(\s+)/);
  const hit = (k: number): boolean => terms.has(clean(parts[k] ?? ""));
  const runs: { text: string; mark: boolean }[] = [];
  parts.forEach((part, k) => {
    const mark = part.trim() ? hit(k) : hit(k - 1) && hit(k + 1);
    const last = runs[runs.length - 1];
    if (last && last.mark === mark) last.text += part;
    else runs.push({ text: part, mark });
  });
  return runs;
}

function SearchIcon({ color }: { color: string }) {
  return (
    <svg width={40} height={40} viewBox="0 0 24 24" fill="none" stroke={color} strokeWidth={2.2} strokeLinecap="round">
      <circle cx="11" cy="11" r="7" />
      <path d="M20 20l-4-4" />
    </svg>
  );
}

function Row({ theme, text, terms, enter, mark, focus }: { theme: VideoTheme; text: string; terms: Set<string>; enter: number; mark: number; focus: number }) {
  return (
    <div
      style={{
        display: "flex",
        alignItems: "center",
        gap: 24,
        height: 96,
        padding: "0 24px",
        borderRadius: theme.radius * 1.2,
        background: withAlpha(theme.primary, 0.09 * focus),
        boxShadow: `inset 0 0 0 2px ${withAlpha(theme.primary, 0.32 * focus)}`,
        opacity: enter,
        transform: `translateY(${(1 - enter) * -18}px)`,
      }}
    >
      <div style={{ width: 52, height: 52, flexShrink: 0, borderRadius: 14, background: theme.muted, display: "flex", flexDirection: "column", justifyContent: "center", gap: 7, padding: "0 13px" }}>
        <div style={{ height: 4, borderRadius: 2, background: withAlpha(theme.mutedForeground, 0.7) }} />
        <div style={{ height: 4, width: "65%", borderRadius: 2, background: withAlpha(theme.mutedForeground, 0.45) }} />
      </div>
      <div style={{ flex: 1, fontSize: 36, letterSpacing: "-0.01em", color: theme.cardForeground, whiteSpace: "nowrap", overflow: "hidden" }}>
        {segments(text, terms).map((seg, i) =>
          seg.mark ? (
            <span key={i} style={{ fontWeight: 600, borderRadius: 6, padding: "0 4px", margin: "0 -4px", background: withAlpha(theme.primary, 0.18 * mark), color: theme.cardForeground }}>
              {seg.text}
            </span>
          ) : (
            <span key={i} style={{ color: withAlpha(theme.cardForeground, 0.78) }}>
              {seg.text}
            </span>
          ),
        )}
      </div>
      <div style={{ fontSize: 26, fontWeight: 500, color: theme.mutedForeground, padding: "8px 16px", borderRadius: 10, border: `1px solid ${theme.border}`, opacity: focus }}>
        Open ↵
      </div>
    </div>
  );
}

/** Type a query, then drop in results with the matching words marked. */
export function SearchBar({
  query = "design tokens",
  results = ["Design tokens for colour and type", "Sharing tokens across every app", "Naming design tokens well", "Design review checklist"],
  placeholder = "Search everything",
  theme: themeOverride,
  font,
}: SearchBarProps) {
  const theme = useVideoTheme(themeOverride);
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const family = pickFont(font, theme, INTER);

  const enter = easings.out(progress(frame, 0, FIELD_FRAMES));
  const cps = Math.max(16, query.length / 1.0);
  const value = typed(query, frame, TYPE_AT, fps, cps);
  const typing = value.length < query.length && frame >= TYPE_AT;
  const rise = easings.inOut(progress(frame, RISE_AT, RISE_FRAMES));
  const top = START_TOP + (END_TOP - START_TOP) * rise;
  const panel = easings.out(progress(frame, ROWS_AT - 6, 14));
  const focus = easings.out(progress(frame, FOCUS_AT, 12));
  const terms = new Set(query.split(/\s+/).map(clean).filter(Boolean));
  const count = easings.out(progress(frame, ROWS_AT + 10, 12));

  return (
    <AbsoluteFill style={{ background: theme.background, fontFamily: family }}>
      <div style={{ position: "absolute", left: LEFT, top, width: WIDTH, opacity: enter, transform: `scale(${0.96 + 0.04 * enter})` }}>
        <TextField
          theme={theme}
          value={value}
          placeholder={placeholder}
          state={frame < TYPE_AT - 4 ? "idle" : typing ? "typing" : "focused"}
          fontSize={42}
          fontFamily={family}
          leading={<SearchIcon color={theme.mutedForeground} />}
          trailing={
            <span style={{ fontSize: 28, color: theme.mutedForeground, opacity: count, whiteSpace: "nowrap" }}>
              {results.length} results
            </span>
          }
        />
      </div>
      {panel > 0 ? (
        <div
          style={{
            position: "absolute",
            left: LEFT,
            top: top + 128,
            width: WIDTH,
            padding: 14,
            display: "flex",
            flexDirection: "column",
            gap: 6,
            borderRadius: theme.radius * 2,
            background: theme.card,
            border: `1px solid ${theme.border}`,
            boxShadow: `0 40px 80px -40px ${withAlpha(theme.foreground, 0.22)}`,
            opacity: panel,
            transform: `translateY(${(1 - panel) * -16}px)`,
          }}
        >
          {results.map((text, i) => {
            const at = ROWS_AT + i * ROW_GAP;
            return (
              <Row
                key={`${text}-${i}`}
                theme={theme}
                text={text}
                terms={terms}
                enter={easings.out(progress(frame, at, 14))}
                mark={easings.out(progress(frame, at + 10, 12))}
                focus={i === 0 ? focus : 0}
              />
            );
          })}
        </div>
      ) : null}
    </AbsoluteFill>
  );
}
